00013 static void write_jump(uint8_t *address, const uint8_t *jump_target)
00014 {
00015 #ifdef _M_IX86
00016     DWORD protect = PAGE_READWRITE;
00017     VirtualProtect(address, 5, protect, &protect);
00018 
00019     // JMP
00020     address[0] = 0xE9;
00021     *reinterpret_cast<int32_t *>(address + 1) = jump_target - (address + 5);
00022 
00023     VirtualProtect(address, 5, protect, &protect);
00024 #endif
00025 #ifdef _M_AMD64
00026     DWORD protect = PAGE_READWRITE;
00027     VirtualProtect(address, 12, protect, &protect);
00028 
00029     // MOV RAX, [target_address]
00030     // JMP RAX
00031     address[0] = 0x48;
00032     address[1] = 0xB8;
00033     *reinterpret_cast<uint64_t *>(address + 2) = reinterpret_cast<uintptr_t>(jump_target);
00034     address[10] = 0xFF;
00035     address[11] = 0xE0;
00036 
00037     VirtualProtect(address, 12, protect, &protect);
00038 #endif
00039 }
