00041 static uint8_t *find_free_memory_region(uint8_t *address, size_t size)
00042 {
00043 #ifdef _M_AMD64
00044     SYSTEM_INFO sysinfo;
00045     MEMORY_BASIC_INFORMATION meminfo;
00046     GetSystemInfo(&sysinfo);
00047 
00048     address -= reinterpret_cast<uintptr_t>(address) % sysinfo.dwAllocationGranularity;
00049     address += sysinfo.dwAllocationGranularity;
00050     auto maxaddress = static_cast<uint8_t *>(sysinfo.lpMaximumApplicationAddress);
00051     maxaddress -= size;
00052 
00053     while (address < maxaddress)
00054     {
00055         if (VirtualQuery(address, &meminfo, sizeof(meminfo)) == 0)
00056             break;
00057 
00058         if (meminfo.State == MEM_FREE)
00059             return address;
00060 
00061         address = static_cast<uint8_t *>(meminfo.BaseAddress) + meminfo.RegionSize;
00062 
00063         // Round up to the next allocation granularity
00064         address += sysinfo.dwAllocationGranularity - 1;
00065         address -= reinterpret_cast<uintptr_t>(address) % sysinfo.dwAllocationGranularity;
00066     }
00067 #endif
00068     return nullptr;
00069 }
