00071 struct thread_scope_guard : scoped_handle
00072 {
00073     thread_scope_guard() :
00074         scoped_handle(CreateToolhelp32Snapshot(TH32CS_SNAPTHREAD, 0))
00075     {
00076         if (handle == INVALID_HANDLE_VALUE)
00077             return;
00078 
00079         THREADENTRY32 te = { sizeof(te) };
00080 
00081         if (Thread32First(handle, &te) && te.dwSize >= FIELD_OFFSET(THREADENTRY32, th32ThreadID) + sizeof(te.th32ThreadID))
00082         {
00083             do
00084             {
00085                 if (te.th32OwnerProcessID != GetCurrentProcessId() || te.th32ThreadID == GetCurrentThreadId())
00086                     continue; // Do not suspend the current thread (which belongs to blink)
00087 
00088                 const scoped_handle thread = OpenThread(THREAD_SUSPEND_RESUME, FALSE, te.th32ThreadID);
00089 
00090                 if (thread == nullptr)
00091                     continue;
00092 
00093                 SuspendThread(thread);
00094             }
00095             while (Thread32Next(handle, &te));
00096         }
00097     }
00098     ~thread_scope_guard()
00099     {
00100         if (handle == INVALID_HANDLE_VALUE)
00101             return;
00102 
00103         THREADENTRY32 te = { sizeof(te) };
00104 
00105         if (Thread32First(handle, &te) && te.dwSize >= FIELD_OFFSET(THREADENTRY32, th32ThreadID) + sizeof(te.th32ThreadID))
00106         {
00107             do
00108             {
00109                 if (te.th32OwnerProcessID != GetCurrentProcessId() || te.th32ThreadID == GetCurrentThreadId())
00110                     continue;
00111 
00112                 const scoped_handle thread = OpenThread(THREAD_SUSPEND_RESUME, FALSE, te.th32ThreadID);
00113 
00114                 if (thread == nullptr)
00115                     continue;
00116 
00117                 ResumeThread(thread);
00118             }
00119             while (Thread32Next(handle, &te));
00120         }
00121     }
00122 };
