00124 bool blink::application::link(const std::filesystem::path &path)
00125 {
00126     // Object file can be a normal COFF or an extended COFF
00127     COFF_HEADER header;
00128     const scoped_handle file = open_coff_file(path, header);
00129     if (file == INVALID_HANDLE_VALUE)
00130         return false;
00131 
00132     return !header.is_extended() ?
00133         link<IMAGE_SYMBOL>(file, header.obj) :
00134         link<IMAGE_SYMBOL_EX>(file, header.bigobj);
00135 }
