00137 template <typename SYMBOL_TYPE, typename HEADER_TYPE>
00138 bool blink::application::link(HANDLE file, const HEADER_TYPE &header)
00139 {
00140     thread_scope_guard _scope_guard_; // Make sure the application doesn't access any of the code pages while they are being modified
00141 
00142 #ifdef _M_IX86
00143     if (header.Machine != IMAGE_FILE_MACHINE_I386)
00144 #endif
00145 #ifdef _M_AMD64
00146     if (header.Machine != IMAGE_FILE_MACHINE_AMD64)
00147 #endif
00148     {
00149         print("Input file is not of a valid format or was compiled for a different processor architecture.");
00150         return false;
00151     }
00152 
00153     // Read section headers from input file (there is no optional header in COFF files, so it is right after the header read above)
00154     std::vector<IMAGE_SECTION_HEADER> sections(header.NumberOfSections);
00155     if (DWORD read; !ReadFile(file, sections.data(), header.NumberOfSections * sizeof(IMAGE_SECTION_HEADER), &read, nullptr))
00156     {
00157         print("Failed to read an image file sections.");
00158         return false;
00159     }
00160 
00161     // Read symbol table from input file
00162     SetFilePointer(file, header.PointerToSymbolTable, nullptr, FILE_BEGIN);
00163 
00164     std::vector<SYMBOL_TYPE> symbols(header.NumberOfSymbols);
00165     if (DWORD read; !ReadFile(file, symbols.data(), header.NumberOfSymbols * sizeof(SYMBOL_TYPE), &read, nullptr))
00166     {
00167         print("Failed to read an image file symbols.");
00168         return false;
00169     }
00170 
00171     // The string table follows after the symbol table and is usually at the end of the file
00172     const DWORD string_table_size = GetFileSize(file, nullptr) - (header.PointerToSymbolTable + header.NumberOfSymbols * sizeof(SYMBOL_TYPE));
00173 
00174     std::vector<char> strings(string_table_size);
00175     if (DWORD read; !ReadFile(file, strings.data(), string_table_size, &read, nullptr))
00176     {
00177         print("Failed to read a string table.");
00178         return false;
00179     }
00180 
00181     // Calculate total module size
00182     SIZE_T allocated_module_size = 0;
00183 
00184     for (const IMAGE_SECTION_HEADER &section : sections)
00185     {
00186         // Add space for section data and potential alignment
00187         allocated_module_size += 256 + section.SizeOfRawData + section.NumberOfRelocations * sizeof(IMAGE_RELOCATION);
00188 
00189 #ifdef _M_AMD64
00190         // Add space for relay thunk
00191         if (section.Characteristics & IMAGE_SCN_CNT_CODE)
00192             allocated_module_size += section.NumberOfRelocations * 12;
00193 #endif
00194     }
00195 
00196     // Allocate executable memory region close to the executable image base (this is done so that relative jumps like 'IMAGE_REL_AMD64_REL32' fit into the required 32-bit).
00197     // Successfully loaded object files are never deallocated again to avoid corrupting the function rerouting generated below. The virtual memory is freed at process exit by Windows.
00198     const auto module_base = static_cast<BYTE *>(VirtualAlloc(find_free_memory_region(_image_base, allocated_module_size), allocated_module_size, MEM_RESERVE | MEM_COMMIT, PAGE_EXECUTE_READWRITE));
00199 
00200     if (module_base == nullptr)
00201     {
00202         print("Failed to allocate executable memory region.");
00203         return false;
00204     }
00205 
00206     // Initialize sections
00207     auto section_base = module_base;
00208 
00209     for (IMAGE_SECTION_HEADER &section : sections)
00210     {
00211         // Skip over all sections that do not need linking
00212         if (section.Characteristics & (IMAGE_SCN_LNK_INFO | IMAGE_SCN_LNK_REMOVE | IMAGE_SCN_MEM_DISCARDABLE))
00213         {
00214             section.PointerToRawData = 0xFFFFFFFF; // Mark this section as being unused
00215             section.NumberOfRelocations = 0; // Ensure that these are not handled by relocation below
00216             continue;
00217         }
00218 
00219         // Check section alignment
00220         UINT_PTR alignment = section.Characteristics & IMAGE_SCN_ALIGN_MASK;
00221         alignment = alignment ? 1 << ((alignment >> 20) - 1) : 1;
00222 
00223         // Align section memory base pointer to its required alignment
00224         section_base = reinterpret_cast<BYTE *>((reinterpret_cast<UINT_PTR>(section_base) + (alignment - 1)) & ~(alignment - 1));
00225 
00226         // Uninitialized sections do not have any data attached and they were already zeroed by 'VirtualAlloc', so skip them here
00227         if (section.PointerToRawData != 0)
00228         {
00229             SetFilePointer(file, section.PointerToRawData, nullptr, FILE_BEGIN);
00230 
00231             if (DWORD read; !ReadFile(file, section_base, section.SizeOfRawData, &read, nullptr))
00232             {
00233                 print("Failed to read a section raw data.");
00234                 return false;
00235             }
00236         }
00237 
00238         section.PointerToRawData = static_cast<DWORD>(section_base - module_base);
00239         section_base += section.SizeOfRawData;
00240 
00241         // Read any relocation data attached to this section
00242         if (section.PointerToRelocations != 0)
00243         {
00244             SetFilePointer(file, section.PointerToRelocations, nullptr, FILE_BEGIN);
00245 
00246             if (DWORD read; !ReadFile(file, section_base, section.NumberOfRelocations * sizeof(IMAGE_RELOCATION), &read, nullptr))
00247             {
00248                 print("Failed to read relocations.");
00249                 return false;
00250             }
00251         }
00252 
00253         section.PointerToRelocations = static_cast<DWORD>(section_base - module_base);
00254         section_base += section.NumberOfRelocations * sizeof(IMAGE_RELOCATION);
00255 
00256 #if 0
00257         // Protect section memory with requested protection flags
00258         DWORD protect = PAGE_NOACCESS;
00259 
00260         switch (section.Characteristics & (IMAGE_SCN_MEM_EXECUTE | IMAGE_SCN_MEM_READ | IMAGE_SCN_MEM_WRITE))
00261         {
00262         case IMAGE_SCN_MEM_READ:
00263             protect = PAGE_READONLY;
00264             break;
00265         case IMAGE_SCN_MEM_READ | IMAGE_SCN_MEM_WRITE:
00266             protect = PAGE_READWRITE;
00267             break;
00268         case IMAGE_SCN_MEM_EXECUTE:
00269             protect = PAGE_EXECUTE;
00270             break;
00271         case IMAGE_SCN_MEM_EXECUTE | IMAGE_SCN_MEM_READ:
00272             protect = PAGE_EXECUTE_READ;
00273             break;
00274         case IMAGE_SCN_MEM_EXECUTE | IMAGE_SCN_MEM_READ | IMAGE_SCN_MEM_WRITE:
00275             protect = PAGE_EXECUTE_READWRITE;
00276             break;
00277         }
00278 
00279         if (section.Characteristics & IMAGE_SCN_MEM_NOT_CACHED)
00280             protect |= PAGE_NOCACHE;
00281 
00282         if (!VirtualProtect(module_base + section.PointerToRawData, section.SizeOfRawData, protect, &protect))
00283             print("Failed to protect section '" + std::string(reinterpret_cast<const char(&)[]>(section.Name)) + "'.");
00284 #endif
00285     }
00286 
00287     // Resolve internal and external symbols
00288     std::vector<BYTE *> local_symbol_addresses(header.NumberOfSymbols);
00289     std::vector<std::pair<BYTE *, const BYTE *>> image_function_relocations;
00290 
00291     for (DWORD i = 0; i < header.NumberOfSymbols; i++)
00292     {
00293         BYTE *target_address = nullptr;
00294         const SYMBOL_TYPE &symbol = symbols[i];
00295 
00296         // Get symbol name from string table if it is a long name
00297         std::string symbol_name;
00298         if (symbol.N.Name.Short == 0)
00299         {
00300             assert(symbol.N.Name.Long < string_table_size);
00301 
00302             symbol_name = strings.data() + symbol.N.Name.Long;
00303         }
00304         else
00305         {
00306             const auto short_name = reinterpret_cast<const char *>(symbol.N.ShortName);
00307 
00308             symbol_name = std::string(short_name, strnlen(short_name, IMAGE_SIZEOF_SHORT_NAME));
00309         }
00310 
00311         const auto symbol_table_lookup = _symbols.find(symbol_name);
00312 
00313         if (symbol.StorageClass == IMAGE_SYM_CLASS_EXTERNAL && symbol.SectionNumber == IMAGE_SYM_UNDEFINED)
00314         {
00315             if (symbol_table_lookup == _symbols.end())
00316             {
00317                 VirtualFree(module_base, 0, MEM_RELEASE);
00318 
00319                 print("Unresolved external symbol '" + symbol_name + "'.");
00320                 return false;
00321             }
00322 
00323             target_address = static_cast<BYTE *>(symbol_table_lookup->second);
00324         }
00325         else if (symbol.StorageClass == IMAGE_SYM_CLASS_WEAK_EXTERNAL)
00326         {
00327             if (symbol_table_lookup != _symbols.end())
00328             {
00329                 target_address = static_cast<BYTE *>(symbol_table_lookup->second);
00330             }
00331             else if (symbol.NumberOfAuxSymbols != 0)
00332             {
00333                 const auto aux_symbol = reinterpret_cast<const IMAGE_AUX_SYMBOL_EX &>(symbols[i + 1]).Sym;
00334 
00335                 assert(aux_symbol.WeakDefaultSymIndex < i && "Unexpected symbol ordering for weak external symbol.");
00336 
00337                 target_address = local_symbol_addresses[aux_symbol.WeakDefaultSymIndex];
00338             }
00339             else
00340             {
00341                 VirtualFree(module_base, 0, MEM_RELEASE);
00342 
00343                 print("Unresolved weak external symbol '" + symbol_name + "'.");
00344                 return false;
00345             }
00346         }
00347         else if (symbol.SectionNumber > IMAGE_SYM_UNDEFINED)
00348         {
00349             const IMAGE_SECTION_HEADER &section = sections[symbol.SectionNumber - 1];
00350 
00351             if (section.PointerToRawData != 0xFFFFFFFF) // Skip sections that do not need linking (see section initialization above)
00352             {
00353                 target_address = module_base + section.PointerToRawData + symbol.Value;
00354 
00355                 if (symbol_table_lookup != _symbols.end() && symbol_name != reinterpret_cast<const char(&)[]>(section.Name))
00356                 {
00357                     const auto old_address = static_cast<BYTE *>(symbol_table_lookup->second);
00358 
00359                     if (ISFCN(symbol.Type))
00360                     {
00361                         image_function_relocations.push_back({ old_address, target_address });
00362                     }
00363                     else if (strcmp(reinterpret_cast<const char *>(section.Name), ".bss") == 0 || strcmp(reinterpret_cast<const char *>(section.Name), ".data") == 0)
00364                     {
00365                         // Continue to use existing data from previous uninitialized (.bss) and initialized (.data) sections instead of replacing it
00366                         target_address = old_address;
00367                     }
00368                 }
00369             }
00370         }
00371 
00372         _symbols[symbol_name] = local_symbol_addresses[i] = target_address;
00373 
00374         i += symbol.NumberOfAuxSymbols;
00375     }
00376 
00377     // Perform relocation on each section
00378     for (const IMAGE_SECTION_HEADER &section : sections)
00379     {
00380         const auto section_relocation_table = reinterpret_cast<const IMAGE_RELOCATION *>(module_base + section.PointerToRelocations);
00381 
00382         for (unsigned int k = 0; k < section.NumberOfRelocations; ++k)
00383         {
00384             const IMAGE_RELOCATION &relocation = section_relocation_table[k];
00385             const auto relocation_address = module_base + section.PointerToRawData + section.VirtualAddress + relocation.VirtualAddress;
00386             auto target_address = local_symbol_addresses[relocation.SymbolTableIndex];
00387 
00388 #ifdef _M_AMD64
00389             // Add relay thunk if distance to target exceeds 32-bit range
00390             if (target_address - relocation_address > 0xFFFFFFFF && ISFCN(symbols[relocation.SymbolTableIndex].Type))
00391             {
00392                 write_jump(section_base, target_address);
00393 
00394                 target_address = section_base;
00395                 section_base += 12;
00396             }
00397 #endif
00398             switch (relocation.Type)
00399             {
00400 #ifdef _M_IX86
00401             // No relocation necessary
00402             case IMAGE_REL_I386_ABSOLUTE:
00403                 break;
00404             // Absolute virtual address
00405             case IMAGE_REL_I386_DIR32:
00406                 *reinterpret_cast<uint32_t *>(relocation_address) = reinterpret_cast<uintptr_t>(target_address);
00407                 break;
00408             // Relative virtual address to __ImageBase
00409             case IMAGE_REL_I386_DIR32NB:
00410                 *reinterpret_cast< int32_t *>(relocation_address) = target_address - _image_base;
00411                 break;
00412             // Relative to next instruction after relocation
00413             case IMAGE_REL_I386_REL32:
00414                 *reinterpret_cast< int32_t *>(relocation_address) = target_address - (relocation_address + 4);
00415                 break;
00416             case IMAGE_REL_I386_SECREL:
00417                 *reinterpret_cast<uint32_t *>(relocation_address) = reinterpret_cast<uintptr_t>(target_address) & 0xFFF; // TODO: This was found by comparing generated ASM, probably not correct
00418                 break;
00419 #endif
00420 #ifdef _M_AMD64
00421             // Absolute virtual 64-bit address
00422             case IMAGE_REL_AMD64_ADDR64:
00423                 *reinterpret_cast<uint64_t *>(relocation_address) = reinterpret_cast<uintptr_t>(target_address);
00424                 break;
00425             // Absolute virtual 32-bit address
00426             case IMAGE_REL_AMD64_ADDR32:
00427                 assert(reinterpret_cast<uint64_t>(target_address) >> 32 == 0 && "Address overflow in absolute relocation.");
00428                 *reinterpret_cast<uint32_t *>(relocation_address) = reinterpret_cast<uintptr_t>(target_address) & 0xFFFFFFFF;
00429                 break;
00430             // Relative virtual address to __ImageBase
00431             case IMAGE_REL_AMD64_ADDR32NB:
00432                 assert(target_address - _image_base == static_cast<int32_t>(target_address - _image_base) && "Address overflow in relative relocation.");
00433                 *reinterpret_cast< int32_t *>(relocation_address) = static_cast<int32_t>(target_address - _image_base);
00434                 break;
00435             // Relative virtual address to next instruction after relocation
00436             case IMAGE_REL_AMD64_REL32:
00437             case IMAGE_REL_AMD64_REL32_1:
00438             case IMAGE_REL_AMD64_REL32_2:
00439             case IMAGE_REL_AMD64_REL32_3:
00440             case IMAGE_REL_AMD64_REL32_4:
00441             case IMAGE_REL_AMD64_REL32_5:
00442                 assert(target_address - relocation_address == static_cast<int32_t>(target_address - relocation_address) && "Address overflow in relative relocation.");
00443                 *reinterpret_cast< int32_t *>(relocation_address) = static_cast<int32_t>(target_address - (relocation_address + 4 + (relocation.Type - IMAGE_REL_AMD64_REL32)));
00444                 break;
00445             case IMAGE_REL_AMD64_SECREL:
00446                 *reinterpret_cast<uint32_t *>(relocation_address) = reinterpret_cast<uintptr_t>(target_address) & 0xFFF; // TODO: This was found by comparing generated ASM, probably not correct
00447                 break;
00448 #endif
00449             default:
00450                 print("Unimplemented relocation type '" + std::to_string(relocation.Type) + "'.");
00451                 break;
00452             }
00453         }
00454     }
00455 
00456     // Reroute old functions to new code
00457     for (const auto &relocation : image_function_relocations)
00458         write_jump(relocation.first, relocation.second);
00459 
00460     FlushInstructionCache(GetCurrentProcess(), module_base, allocated_module_size);
00461 
00462     print("Successfully linked object file into executable image.");
00463 
00464     return true;
00465 }
